func (this *Whitebit) HandleTicker(client any, message map[string]any) any {
	//
	//   {
	//       "method": "market_update",
	//       "params": [
	//         "BTC_USDT",
	//         {
	//           "close": "22293.86",
	//           "deal": "1986990019.96552952",
	//           "high": "24360.7",
	//           "last": "22293.86",
	//           "low": "20851.44",
	//           "open": "24076.12",
	//           "period": 86400,
	//           "volume": "87016.995668"
	//         }
	//       ],
	//       "id": null
	//   }
	//
	var tickers any = this.SafeList(message, "params", []any{})
	var marketId *string = this.SafeString(tickers, 0)
	var market any = this.SafeMarket(marketId)
	var symbol any = ccxt.GetValue(market, "symbol")
	var rawTicker any = this.SafeDict(tickers, 1, map[string]any{})
	var messageHash any = ccxt.Add("ticker"+":", symbol)
	var ticker any = this.ParseTicker(rawTicker, market)
	ccxt.AddElementToObject(this.Tickers, symbol, ticker)
	// watchTicker
	client.(ccxt.ClientInterface).Resolve(ticker, messageHash)
	// watchTickers
	var messageHashes []string = ccxt.ObjectKeys(client.(ccxt.ClientInterface).GetFutures())
	for i := 0; i < len(messageHashes); i++ {
		var currentMessageHash string = ccxt.GetValue(messageHashes, i).(string)
		if (strings.Index(currentMessageHash, "tickers") >= 0) && (ccxt.GetIndexOf(currentMessageHash, symbol) >= 0) {
			// Example: user calls watchTickers with ['LTC/USDT', 'ETH/USDT']
			// the associated messagehash will be: 'tickers:LTC/USDT:ETH/USDT'
			// since we only have access to a single symbol at a time
			// we have to do a reverse lookup into the tickers hashes
			// and check if the current symbol is a part of one or more
			// tickers hashes and resolve them
			// user might have multiple watchTickers promises
			// watchTickers ( ['LTC/USDT', 'ETH/USDT'] ), watchTickers ( ['ETC/USDT', 'DOGE/USDT'] )
			// and we want to make sure we resolve only the correct ones
			client.(ccxt.ClientInterface).Resolve(ticker, currentMessageHash)
		}
	}
	return message
}

